from pathlib import Path
import json,collections
P=Path(__file__).resolve().parent;results=[]
for name in json.loads((P/'accepted-cases.json').read_text()):
 f=P/name/'runtime/bs1-observer/irq.jsonl'
 if not f.exists():continue
 stack=[];pairs=[];clocks=[];clockstack=[];wrong=[];callers=collections.Counter()
 for line in f.open():
  r=json.loads(line)
  if r['kind']=='service-entry':stack.append(r)
  elif r['kind']=='service-exit':
   first=stack.pop();assert first['sp']==r['sp'] and all(x==y for i,(x,y) in enumerate(zip(first['scratch'],r['scratch'])) if i!=14) # RW38 intentionally excludes native service from idle time
   assert first['selectors']==r['selectors'] and first['mask0']==r['mask0'] and first['mask1']==r['mask1']
   if first['controller_mode']==0 and first['controller_state']==0:
    pairs.append(r['seconds']-first['seconds']);callers[(first['caller']['psw']&255,first['caller']['wsr_mask1']>>8)]+=1
  elif r['kind']=='service-clock-start':clockstack.append(r)
  elif r['kind']=='service-clock-end':
   first=clockstack.pop();gap=r['seconds']-first['seconds']
   if first.get('controller_mode')==0 and first.get('controller_state')==0:
    assert gap<.065536;raw=(r['tick']-first['tick'])&65535;assert abs(raw-gap*1e6)<2;clocks.append(gap)
 assert not stack and not clockstack
 results.append(dict(case=name,pairs=len(pairs),clock_intervals=len(clocks),maximum_suspended_service_seconds=max(pairs,default=0),maximum_timer_read_interval_seconds=max(clocks,default=0),original_masks={str(k):v for k,v in callers.items()}))
(P/'service-audit.json').write_text(json.dumps(dict(passed=True,cases=results),indent=2)+'\n');print(json.dumps(results,indent=2))

