from pathlib import Path
import json,collections
P=Path(__file__).resolve().parent;cases=[]
for stage in ['save','reload']:
 f=P/'stock-save-load'/stage/'policy-observer/native-policy.jsonl';rows=[json.loads(line) for line in f.open()];state=None;cdb=[];transitions=[]
 for r in rows:
  # The preliminary observer's redundant physical-state field used an incorrect
  # address. Ignore that field entirely; recover1BA5 from its actual bus writes.
  if r['kind']=='controller-state' and r['mask']&0xff00:state=(r['value']>>8)&255;transitions.append(dict(seconds=r['seconds'],mode=state,pc=r['pc']))
  if r['kind']=='controller-request':assert ((r['value']>>8)&255)==state,(stage,r,state)
  if r['kind']=='cdb':cdb.append(dict(seconds=r['seconds'],bytes=r['bytes'],native_mode=state,requested=r['requested']))
 bulk=[r for r in cdb if r['bytes'][0] in (0x28,0x2a) and ((r['bytes'][7]<<8)|r['bytes'][8])>=16]
 assert bulk and all(r['native_mode']==0 and r['requested']==0 for r in bulk),(stage,collections.Counter((r['native_mode'],r['requested']) for r in bulk))
 cases.append(dict(stage=stage,bulk_commands=len(bulk),reads=sum(r['bytes'][0]==0x28 for r in bulk),writes=sum(r['bytes'][0]==0x2a for r in bulk),transitions=transitions,matched_commands=bulk))
report=dict(passed=True,stock_workflow=json.loads((P/'stock-save-load/save-results.json').read_text()),cases=cases,observer_correction='Do not use the preliminary trace state field at837A5. Native mode is independently reconstructed from masked writes to1BA5 under data0=0204 (physical82BA5), then cross-checked against4F8D comparison reads. Corrected observer used for all browser candidate cases.',scope='Named stock native SCSI initialize/Save and fresh-process Load with exact119808 PCM bytes and playback/release. Discovery/small reads are not claimed universally muted.')
(P/'stock-policy-proof.json').write_text(json.dumps(report,indent=2)+'\n');print('PASS stock bulk commands suspended:',[(c['stage'],c['reads'],c['writes']) for c in cases])

