from pathlib import Path
import json,pypcode,sys
P=Path(__file__).resolve().parent;A=P/'candidate-quiesce-v2';image=(A/'full.img').read_bytes();ctx=pypcode.Context('MCS96:LE:16:default');rows={}
for page,start,end in [(0,0xcad1,0xcbcf),(31,0x4000,0x405c),(0,0xcd1f,0xcd5d),(15,0x138,0x13c)]:
 off=0x4800+(page<<10)+(start&0x3fff);ins=ctx.disassemble(image[off:off+end-start],base_address=start).instructions;assert sum(i.length for i in ins)==end-start
 for i in ins:rows[i.addr.offset]=dict(pc=i.addr.offset,bytes=image[off+i.addr.offset-start:off+i.addr.offset-start+i.length].hex(),op=i.mnem,body=i.body,n=i.length)
forced={0x4047:0x404b,0xcb6c:0xcbcb}
seen=set()
def bound(pc,trail=()):
 assert pc not in trail,('cycle',trail,pc)
 if pc in forced:edges=[forced[pc]]
 else:
  r=rows[pc];op=r['op'];n=pc+r['n']
  if op=='RET':return (1,[pc])
  if op in ('LCALL','SCALL'):
   target=int(r['body'].split()[-1],16)&65535;inside,path=bound(target,trail+(pc,));tail,suffix=bound(n,trail+(pc,));return (1+inside+tail,[pc]+path+suffix)
  if op in ('LJMP','SJMP'):edges=[int(r['body'].split()[-1],16)&65535]
  elif op.startswith('J'):edges=[n,int(r['body'].split()[-1],16)&65535]
  else:edges=[n]
 result=max((bound(v,trail+(pc,)) for v in edges),key=lambda x:x[0]);return 1+result[0],[pc]+result[1]
result={hex(root):bound(root) for root in [0xcad1,0x138]}
for name,(count,path) in result.items():
 assert not any(rows[v]['op'] in ['DIV','DIVU','MUL','MULU','DJNZ','DJNZW','BR'] for v in path)
 print(name,count,'instructions',count*20/8,'timer ticks at conservative20 state-times/instruction')
(P/'suspended-paths.json').write_text(json.dumps(dict(conditions=['Native mode R9D=0 and cached1BA5=0 for entire command','Native IRQ vectors/mappings and normal UART arrival31.25kbps profile','No unmodeled external READY stretch or unrelated IRQ owner'],forced_edges={hex(k):hex(v) for k,v in forced.items()},bounds={k:dict(instructions=v[0],longest_path=[hex(pc) for pc in v[1]]) for k,v in result.items()},decoded=list(rows.values()),limitation='Instruction counts are static under the declared mode predicates. Cycle-envelope comparison is a native CPU-model bound, not a calibrated physical WCET.'),indent=2)+'\n')
